4 //
5 // Core Implemenation module for Serial Peripheral Interface (SPI) Host IP.
6 //
7 
8 `include "common_cells/assertions.svh"
9 
10 module spi_host_fsm
11   import spi_host_cmd_pkg::*;
12 #(
13   parameter  int NumCS = 1
14 ) (
15   input                              clk_i,
16   input                              rst_ni,
17   input                              en_i,
18   input  command_t                   command_i,
19   input                              command_valid_i,
20   output logic                       command_ready_o,
21   output logic                       sck_o,
22   output logic [NumCS-1:0]           csb_o,
23   output logic [3:0]                 sd_en_o,
24   output logic                       cmd_end_o,
25   output logic                       wr_en_o,
26   input                              sr_wr_ready_i,
27   output logic                       rd_en_o,
28   input                              sr_rd_ready_i,
29   output logic                       sample_en_o,
30   output logic                       shift_en_o,
31   output logic [1:0]                 speed_o,
32   output logic                       full_cyc_o,
33   output logic                       rx_stall_o,
34   output logic                       tx_stall_o,
35   output logic                       active_o,
36 
37   input                              sw_rst_i
38 );
39 
40   logic             isIdle;
41   logic [15:0]      clkdiv, clkdiv_q;
42   logic [15:0]      clk_cntr_q, clk_cntr_d;
43   logic             clk_cntr_en;
44 
45   logic [CSW-1:0]   csid;
46   logic [CSW-1:0]   csid_q;
47 
48   logic [3:0]       csnidle, csntrail, csnlead;
49   logic [3:0]       csnidle_q, csntrail_q, csnlead_q;
50   logic             full_cyc, cpha, cpol;
51   logic             full_cyc_q, cpha_q, cpol_q;
52 
53   logic [1:0]       cmd_speed;
54   logic [1:0]       cmd_speed_q;
55   logic             cmd_wr_en, cmd_wr_en_q;
56   logic             cmd_rd_en, cmd_rd_en_q;
57   // cmd_len needs no data latching as it is only used at the very start of a command.
58   // The corresponding register, cmd_len_q, would create a warning at synthesis
59   logic [8:0]       cmd_len;
60   logic             csaat;
61   logic             csaat_q;
62 
63   logic [2:0]       bit_cntr_d, bit_cntr_q;
64   logic [8:0]       byte_cntr_d, byte_cntr_q;
65   logic [3:0]       lead_cntr_d, idle_cntr_d, trail_cntr_d;
66   logic [3:0]       lead_cntr_q, idle_cntr_q, trail_cntr_q;
67   logic             last_bit, last_byte;
68 
69   logic             state_changing;
70   logic             byte_starting, byte_starting_cpha0, byte_starting_cpha1;
71   logic             bit_shifting, bit_shifting_cpha0, bit_shifting_cpha1;
72   logic             byte_ending, byte_ending_cpha0, byte_ending_cpha1;
73   logic             lead_starting;
74   logic             trail_starting;
75   logic             idle_starting;
76 
77   logic             sample_en_d, sample_en_q, sample_en_q2;
78 
79   logic             switch_required;
80   logic             fsm_en;
81   logic             new_command;
82 
83   logic             csb_single_d;
84   logic [NumCS-1:0] csb_q;
85   logic             sck_d, sck_q;
86 
87   logic wr_en_internal, rd_en_internal, sample_en_internal, shift_en_internal;
88 
89   logic stall, stall_q;
90 
91   assign stall = rx_stall_o | tx_stall_o;
92 
93   // suppress output pulses if stalled.
94   assign wr_en_o     = wr_en_internal & ~stall;
95   assign rd_en_o     = rd_en_internal & ~stall;
96   assign sample_en_o = sample_en_internal & ~stall;
97   assign shift_en_o  = shift_en_internal & ~stall;
98 
99   typedef enum logic [2:0] {
100     Idle,
101     WaitLead,
102     InternalClkLow,
103     InternalClkHigh,
104     WaitTrail,
105     WaitIdle,
106     CSBSwitch,
107     IdleCSBActive
108   } spi_host_st_e;
109 
110   // The FSM stall mechanism halts the FSM by preventing the update of any internal registers.
111   // Since most register data values in this do not actually depend on the stall signal, this
112   // means that the stall signal is routed to the enable line of the corresponding flop but does
113   // not influence the and flip-flop data (_d) signals.
114   //
115   // This is not the case for the main FSM state variable, where there there is actually a logical
116   // cyclical dependency to worry about.  The stall variable depends on the FSM state, because an
117   // empty/full data FIFO only stalls the FSM when during states where data is needed from the
118   // FIFO.  Meanwhile, the FSM state depends on the stall variable through the `command_ready_o`
119   // signal. We only want to start processing an incoming command when it has been acknowledged,
120   // and we don't want to acknowledge the next command during a stall condition.
121   //
122   // Linting reports this cyclical dependency as unoptimizable and simulations can hang
123   // if this is not resolved.
124   //
125   // In principle, this cyclical dependency could possibly be broken through careful analysis of
126   // the logical dependencies between these three signals.  However, this may become a
127   // developmental challenge as we revise and debug this block.  So instead we take a simpler
128   // approach of breaking this combinational logic loop with a second FSM state register.
129   //
130   // That said there are then two copies of the FSM state variable
131   // Actual:   The true state of the FSM, which controls the peripheral IOs and the interactions with
132   //           the other blocks.
133   // Prestall: The "tentative" state of the FSM, which can be overridden by stall events. Normally
134   //           this matches the actual state. However when a stall event is recieved, the actual
135   //           state remains unchanged.  Once the stall event is resolved, the actual state is
136   //           updated to match the prestall state.
137   //
138   // The prestall state variable has no combinational logic dependency on the stall signal.
139 
140   spi_host_st_e prestall_st_q, prestall_st_d, actual_st_d, actual_st_q;
141 
142   assign new_command     = command_valid_i && command_ready_o;
143   assign switch_required = command_valid_i && (command_i.csid != csid_q);
144 
145   always_comb begin
146     csid      = new_command ? command_i.csid : csid_q;
147     cpol      = new_command ? command_i.configopts.cpol : cpol_q;
148     cpha      = new_command ? command_i.configopts.cpha : cpha_q;
149     full_cyc  = new_command ? command_i.configopts.full_cyc : full_cyc_q;
150     csnidle   = new_command ? command_i.configopts.csnidle : csnidle_q;
151     csnlead   = new_command ? command_i.configopts.csnlead : csnlead_q;
152     csntrail  = new_command ? command_i.configopts.csntrail : csntrail_q;
153     clkdiv    = new_command ? command_i.configopts.clkdiv : clkdiv_q;
154     csaat     = new_command ? command_i.segment.csaat : csaat_q;
155     // cmd_len needs no data latching as it is only used at the very start of a command.
156     cmd_len   = command_i.segment.len;
157     cmd_rd_en = new_command ? command_i.segment.cmd_rd_en : cmd_rd_en_q;
158     cmd_wr_en = new_command ? command_i.segment.cmd_wr_en : cmd_wr_en_q;
159     cmd_speed = new_command ? command_i.segment.speed : cmd_speed_q;
160   end
161 
162   always_ff @(posedge clk_i or negedge rst_ni) begin
163     if (!rst_ni) begin
164       csid_q      <= {CSW{1'b0}};
165       cpol_q      <= 1'b0;
166       cpha_q      <= 1'b0;
167       full_cyc_q  <= 1'b0;
168       csnidle_q   <= 4'h0;
169       csnlead_q   <= 4'h0;
170       csntrail_q  <= 4'h0;
171       clkdiv_q    <= 16'h0;
172       csaat_q     <= 1'b0;
173       cmd_rd_en_q <= 1'b0;
174       cmd_wr_en_q <= 1'b0;
175       cmd_speed_q <= 2'b00;
176     end else begin
177       csid_q      <= new_command ? csid : csid_q;
178       cpol_q      <= new_command ? cpol : cpol_q;
179       cpha_q      <= new_command ? cpha : cpha_q;
180       full_cyc_q  <= new_command ? full_cyc : full_cyc_q;
181       csnidle_q   <= new_command ? csnidle : csnidle_q;
182       csnlead_q   <= new_command ? csnlead : csnlead_q;
183       csntrail_q  <= new_command ? csntrail : csntrail_q;
184       clkdiv_q    <= new_command ? clkdiv : clkdiv_q;
185       csaat_q     <= new_command ? csaat : csaat_q;
186       cmd_rd_en_q <= new_command ? cmd_rd_en : cmd_rd_en_q;
187       cmd_wr_en_q <= new_command ? cmd_wr_en : cmd_wr_en_q;
188       cmd_speed_q <= new_command ? cmd_speed : cmd_speed_q;
189     end
190   end
191 
192   assign isIdle     = (actual_st_q == Idle) || (actual_st_q == IdleCSBActive);
193 
194   assign active_o   = ~isIdle;
195 
196   assign clk_cntr_d = sw_rst_i              ? 16'h0 :
197                       !clk_cntr_en          ? clk_cntr_q :
198                       isIdle                ? 16'h0 :
199                       new_command           ? clkdiv :
200                       (clk_cntr_q == 16'h0) ? clkdiv :
201                       clk_cntr_q - 1;
202 
203   assign tx_stall_o = wr_en_internal & ~sr_wr_ready_i;
204   assign rx_stall_o = rd_en_internal & ~sr_rd_ready_i;
205   assign clk_cntr_en = en_i;
206   assign fsm_en = (clk_cntr_en && clk_cntr_q == 0);
207 
208   // FSM main body: Controls state transitions and command_ready_o signaling
209   //
210   // command_ready_o Note: New commands should may be acknowled as we enter into the idle condition
211   // with two subtle exceptions:
212   //   1. During stall conditions the FSM does not actually perform transitions and so
213   //      command_ready_o should be held low during stalls regardless of the current state
214   //   2. In cases where the next segment is for a different CSID, command_ready_o is held
215   //      explicitly low to enforce CSNTRAIL, CSIDLE requirements for the previous segment.
216   //      Holding command_ready_o low in this case defers updates of the internal state variables
217   always_comb begin
218     prestall_st_d = actual_st_q;
219     command_ready_o = 1'b0;
220     if (sw_rst_i) begin
221       prestall_st_d = Idle;
222     end else if (stall_q) begin
223       prestall_st_d = prestall_st_q;
224     end else if (fsm_en) begin
225       unique case (actual_st_q)
226         Idle: begin
227           // Initial state, wait for commands.
228           command_ready_o = 1'b1;
229           if (command_valid_i) begin
230             if (command_i.csid != csid_q) begin
231               prestall_st_d = CSBSwitch;
232             end else begin
233               prestall_st_d = WaitLead;
234             end
235           end
236         end
237         WaitLead: begin
238           // Transaction lead: CSB is low, waiting to start sck pulses.
239           if (lead_cntr_q == 4'h0) begin
240             prestall_st_d = InternalClkHigh;
241           end
242         end
243         InternalClkLow: begin
244           // One of two active clock states. sck is low when CPOL=0.
245           prestall_st_d = InternalClkHigh;
246         end
247         InternalClkHigh: begin
248           // One of two active clock states. sck is low when CPOL=0.
249           // Typically often the last state in a command, and so the next state depends on CSAAT,
250           // and of CSAAT is asserted, the details of the subsequent command.
251           if (!last_bit || !last_byte) begin
252             prestall_st_d = InternalClkLow;
253           // Check value of csaat for the previously submitted segment
254           end else if (!csaat_q) begin
255             prestall_st_d = WaitTrail;
256           end else if (!command_valid_i) begin
257             prestall_st_d = IdleCSBActive;
258           end else if (command_i.csid != csid_q) begin
259             prestall_st_d = WaitTrail;
260           end else begin
261             command_ready_o  = 1'b1;
262             prestall_st_d = InternalClkLow;
263           end
264         end
265         WaitTrail: begin
266           // Prepare to enter CSB high idle state by waiting csntrail cycles.
267           if (trail_cntr_q == 4'h0) begin
268             prestall_st_d = WaitIdle;
269           end
270         end
271         WaitIdle: begin
272           // Once CSB is high, wait for the designated number of cyclse before accepting commands.
273           if (idle_cntr_q == 4'h0) begin
274             // ready to accept new command
275             command_ready_o = 1'b1;
276             if (command_valid_i) begin
277               if (switch_required) begin
278                  prestall_st_d = CSBSwitch;
279               end else begin
280                  prestall_st_d = WaitLead;
281               end
282             end else begin
283               prestall_st_d = Idle;
284             end
285           end
286         end
287         CSBSwitch: begin
288           // Insert extra idle cycles when swtiching between CSID, this allows time to switch CPHA,
289           // CPOL and clkdiv settings, as well as guarantee that the idle delay requirements have
290           // been observed for the new device.
291           if (idle_cntr_q == 4'h0) begin
292             prestall_st_d = WaitLead;
293           end else begin
294             prestall_st_d = WaitIdle;
295           end
296         end
297         IdleCSBActive: begin
298           // Wait for new commands, but with CSB held active low.
299           if (command_valid_i) begin
300             if (command_i.csid != csid_q) begin
301               // New command received, but for a different CSID than the last.  Deactivate CSB,
302               // while still adhering to trail and idle time requirements
303               prestall_st_d = WaitTrail;
304               // Explicitly delay command_ready until the end of WaitIdle.  We need to observe
305               // the trail time requirements for the current CSID, so we can't update our
306               // configopts until CSB is high.
307               command_ready_o = 1'b0;
308             end else begin
309               command_ready_o = 1'b1;
310               prestall_st_d = InternalClkLow;
311             end
312           end else begin
313             command_ready_o = 1'b1;
314           end
315         end
316         default: begin
317           command_ready_o  = 1'b0;
318           prestall_st_d = Idle;
319         end
320       endcase
321     end
322   end
323 
324   // All register updates freeze when a stall is detected.
325   // The definition of the stall signal looks ahead to determine whether a conflict is looming.
326   // Thus stall depends on actual_st_d.  Making the actual state depend on stall
327   // would create a circular logic loop, and lint errors.  Therefore stall is applied here, not
328   // in the previous always_comb block;
329 
330   logic stall_resolve;
331 
332   assign stall_resolve = !stall && stall_q;
333   assign actual_st_d   = stall         ? actual_st_q :
334                          stall_resolve ? prestall_st_q :
335                          prestall_st_d;
336 
337   always_ff @(posedge clk_i or negedge rst_ni) begin
338     if (!rst_ni) begin
339       actual_st_q         <= Idle;
340       prestall_st_q       <= Idle;
341       clk_cntr_q          <= 16'h0;
342       stall_q             <= 1'b0;
343     end else begin
344       stall_q             <= stall;
345       prestall_st_q       <= prestall_st_d;
346       actual_st_q         <= actual_st_d;
347       clk_cntr_q          <= stall ? clk_cntr_q : clk_cntr_d;
348     end
349   end
350 
351   assign state_changing = (actual_st_q != prestall_st_d);
352 
353   // The stall signal depends on byte_starting, and since acutal_st_d depends on stall,
354   // byte_starting_cpha0 is based off prestall_st_d.   In the event of a stall
355   // byte_starting may be high for multiple cycles until the stall is resolved.
356   // The rd_en_o and wr_en_o signals held low during a stall, thus the control signals
357   // sent to the byte_merge and byte_sleect blocks are active for only one cycle.
358   assign byte_starting_cpha0 = ~sw_rst_i & state_changing &
359                                ((prestall_st_d == WaitLead) |
360                                 (prestall_st_d == InternalClkLow & bit_cntr_q==0));
361   assign bit_shifting_cpha0  = ~sw_rst_i & state_changing &
362                                (actual_st_d == InternalClkLow & bit_cntr_q != 0);
363   assign byte_ending_cpha0   = ~sw_rst_i & state_changing &
364                                (actual_st_q == InternalClkHigh & bit_cntr_q == 0);
365 
366   // We can calculate byte transitions for CHPA=1 by noting
367   // that in this implmentation, the sck edges have a 1-1
368   // correspondence with FSM transitions.
369   // New bytes are loaded exactly one state transition behind the time
370   // when they would be loaded if CPHA=0
371   always_ff @(posedge clk_i or negedge rst_ni) begin
372     if (!rst_ni) begin
373       byte_starting_cpha1 <= 1'b0;
374       byte_ending_cpha1 <= 1'b0;
375       bit_shifting_cpha1 <= 1'b0;
376     end else begin
377       byte_ending_cpha1   <= (state_changing && !stall) ? byte_ending_cpha0 : 1'b0;
378       byte_starting_cpha1 <= (state_changing && !stall) ? byte_starting_cpha0 : 1'b0;
379       bit_shifting_cpha1  <= (state_changing && !stall) ? bit_shifting_cpha0 : 1'b0;
380     end
381   end
382 
383   assign byte_starting = (cpha == 1'b0) ? byte_starting_cpha0 :
384                                           byte_starting_cpha1;
385 
386   assign byte_ending   = (cpha == 1'b0) ? byte_ending_cpha0 :
387                                           byte_ending_cpha1;
388 
389   assign bit_shifting  = (cpha == 1'b0) ? bit_shifting_cpha0 :
390                                           bit_shifting_cpha1;
391 
392   logic [2:0] shift_size;
393   logic [2:0] start_bit;
394 
395   always_comb begin
396     if (!cmd_rd_en && !cmd_wr_en) begin
397       // direction == 0, means to send out
398       // a fixed number of pulses, NOT bytes.
399       // thus "last_bit" is always asserted,
400       // and the number of pulses is counted
401       // by byte_cntr_d.
402       shift_size = 0;
403       start_bit = 3'h0;
404     end else begin
405       unique case (cmd_speed)
406         Standard: begin
407           shift_size = 3'h1;
408           start_bit  = 3'h7;
409         end
410         Dual:     begin
411           shift_size = 3'h2;
412           start_bit  = 3'h6;
413         end
414         Quad:     begin
415           shift_size = 3'h4;
416           start_bit  = 3'h4;
417         end
418         default: begin
419           // Invalid_speed;
420           shift_size = 3'h1;
421           start_bit  = 3'h1;
422         end
423       endcase
424     end
425   end
426 
427   assign bit_cntr_d = sw_rst_i         ? 3'h0 :
428                       !fsm_en          ? bit_cntr_q :
429                       byte_starting    ? start_bit :
430                       bit_shifting     ? bit_cntr_q - shift_size :
431                       bit_cntr_q;
432 
433   assign last_bit  = (bit_cntr_q == 3'h0);
434   assign last_byte = (byte_cntr_q == 9'h0);
435 
436   assign byte_cntr_d = sw_rst_i    ? 9'h0 :
437                        !fsm_en     ? byte_cntr_q :
438                        new_command ? cmd_len :
439                        byte_ending ? byte_cntr_q - 1 :
440                        byte_cntr_q;
441 
442   assign lead_starting = state_changing && actual_st_d == WaitLead;
443 
444   assign lead_cntr_d = sw_rst_i         ? 4'h0 :
445                        !fsm_en          ? lead_cntr_q :
446                        lead_starting    ? csnlead :
447                        lead_cntr_q == 0 ? 4'h0 :
448                        lead_cntr_q - 1;
449 
450   assign trail_starting = state_changing && actual_st_d == WaitTrail;
451 
452   assign trail_cntr_d = sw_rst_i          ? 4'h0 :
453                         !fsm_en           ? trail_cntr_q :
454                         trail_starting    ? csntrail :
455                         trail_cntr_q == 0 ? 4'h0 :
456                         trail_cntr_q - 1;
457 
458   assign idle_starting = state_changing &&
459                         (actual_st_d == WaitIdle ||
460                          actual_st_d == CSBSwitch);
461 
462   assign idle_cntr_d = sw_rst_i         ? 4'h0 :
463                        !fsm_en          ? idle_cntr_q :
464                        idle_starting    ? csnidle :
465                        idle_cntr_q == 0 ? 4'h0 :
466                        idle_cntr_q - 1;
467 
468   always_ff @(posedge clk_i or negedge rst_ni) begin
469     if (!rst_ni) begin
470       bit_cntr_q   <= 3'h0;
471       byte_cntr_q  <= 9'h0;
472       idle_cntr_q  <= 4'h0;
473       lead_cntr_q  <= 4'h0;
474       trail_cntr_q <= 4'h0;
475     end else begin
476       bit_cntr_q   <= stall ? bit_cntr_q   : bit_cntr_d;
477       byte_cntr_q  <= stall ? byte_cntr_q  : byte_cntr_d;
478       idle_cntr_q  <= stall ? idle_cntr_q  : idle_cntr_d;
479       lead_cntr_q  <= stall ? lead_cntr_q  : lead_cntr_d;
480       trail_cntr_q <= stall ? trail_cntr_q : trail_cntr_d;
481     end
482   end
483 
484   assign wr_en_internal    = byte_starting & cmd_wr_en;
485   assign shift_en_internal = bit_shifting;
486   assign rd_en_internal    = byte_ending & cmd_rd_en;
487   assign speed_o           = cmd_speed;
488   assign sample_en_d       = byte_starting | shift_en_o;
489   assign full_cyc_o        = full_cyc;
490   assign cmd_end_o         = (byte_cntr_q == 'h1) & wr_en_o & sr_wr_ready_i;
491 
492   always_ff @(posedge clk_i or negedge rst_ni) begin
493     if (!rst_ni) begin
494       sample_en_q <= 1'b0;
495       sample_en_q2 <= 1'b0;
496     end else begin
497       sample_en_q  <= (fsm_en && !stall) ? sample_en_d : sample_en_q;
498       sample_en_q2 <= (fsm_en && !stall) ? sample_en_q : sample_en_q2;
499     end
500   end
501 
502   assign sample_en_internal = full_cyc_o ? sample_en_q2 : sample_en_q;
503 
504   always_comb begin
505     unique case (actual_st_d)
506       WaitLead, InternalClkLow, InternalClkHigh, IdleCSBActive, WaitTrail:
507         csb_single_d = 1'b0;
508       default:
509         csb_single_d = 1'b1;
510     endcase
511   end
512 
513   assign sck_d = cpol ? (actual_st_d != InternalClkHigh) :
514                         (actual_st_d == InternalClkHigh);
515 
516   assign sck_o = sck_q;
517 
518   for (genvar ii = 0; ii < NumCS; ii = ii + 1) begin : gen_csb_gen
519     always_ff @(posedge clk_i or negedge rst_ni) begin
520       if (!rst_ni) begin
521         csb_q[ii] <= 1'b1;
522         if (ii == 0) sck_q     <= 1'b0;
523       end else begin
524         csb_q[ii] <= (csid != ii) ? 1'b1 :
525                      !stall       ? csb_single_d :
526                      csb_q[ii];
527         if (ii == 0) sck_q     <= !stall ? sck_d : sck_q;
528       end
529     end
530   end : gen_csb_gen
531 
532   assign csb_o = csb_q;
533 
534   always_comb begin
535     if (&csb_o) begin
536       sd_en_o[3:0] = 4'h0;
537     end else begin
538       unique case (cmd_speed)
539         Standard: begin
540           sd_en_o[0]   = cmd_wr_en;
541           sd_en_o[1]   = 1'b0;
542           sd_en_o[3:2] = 2'b00;
543         end
544         Dual:     begin
